package com.monitoring.agent

import java.io._
import java.nio.file._
import java.util.Base64
import java.util.zip._
import scala.collection.mutable
import scala.util.{Try, Success, Failure}

// Monitoring agent that processes diagnostic bundles uploaded by users
object DiagnosticProcessor {

  sealed trait BundleFormat
  case object CompressedJava extends BundleFormat
  case object PlainText extends BundleFormat
  case object StructuredLog extends BundleFormat

  case class DiagnosticBundle(
    agentId: String,
    timestamp: Long,
    format: BundleFormat,
    payload: Array[Byte],
    metadata: Map[String, String]
  )

  // Registry of safe classes for structured log deserialization
  private val ALLOWED_CLASSES: Set[String] = Set(
    "java.lang.String",
    "java.lang.Integer",
    "java.lang.Long",
    "java.util.HashMap",
    "java.util.ArrayList",
    "scala.collection.immutable.List",
    "scala.collection.immutable.Map",
    "com.monitoring.agent.LogEntry",
    "com.monitoring.agent.MetricSnapshot"
  )

  class SafeObjectInputStream(in: InputStream) extends ObjectInputStream(in) {
    override def resolveClass(desc: ObjectStreamClass): Class[_] = {
      val className = desc.getName
      if (!isClassAllowed(className)) {
        throw new SecurityException(s"Deserialization of class $className is not allowed")
      }
      super.resolveClass(desc)
    }

    private def isClassAllowed(className: String): Boolean = {
      // Allow primitives and arrays of allowed types
      if (className.startsWith("[")) return isClassAllowed(className.substring(1))
      if (className.length == 1) return true // primitive type descriptors
      val normalized = className.replace("L", "").replace(";", "")
      ALLOWED_CLASSES.exists(allowed => normalized.startsWith(allowed) || allowed.startsWith(normalized))
    }
  }

  // Process compressed diagnostic data - handles GZIP streams
  def decompressPayload(data: Array[Byte]): Array[Byte] = {
    val bais = new ByteArrayInputStream(data)
    val gzis = new GZIPInputStream(bais)
    val baos = new ByteArrayOutputStream()
    val buffer = new Array[Byte](4096)
    var bytesRead = 0
    var totalRead = 0L
    val MAX_SIZE = 10 * 1024 * 1024 // 10MB limit

    while ({ bytesRead = gzis.read(buffer); bytesRead != -1 }) {
      totalRead += bytesRead
      if (totalRead > MAX_SIZE) {
        throw new IOException("Decompressed payload exceeds maximum size")
      }
      baos.write(buffer, 0, bytesRead)
    }
    gzis.close()
    baos.toByteArray
  }

  // Validate bundle metadata before processing
  def validateMetadata(metadata: Map[String, String]): Boolean = {
    val requiredKeys = Set("version", "source", "checksum")
    requiredKeys.subsetOf(metadata.keySet) &&
      metadata("version").matches("^\\d+\\.\\d+\\.\\d+$") &&
      metadata("source").matches("^[a-zA-Z0-9_-]+$")
  }

  // Main processing pipeline
  def processBundle(bundle: DiagnosticBundle): Either[String, ProcessingResult] = {
    if (!validateMetadata(bundle.metadata)) {
      return Left("Invalid bundle metadata")
    }

    bundle.format match {
      case PlainText =>
        processPlainText(bundle.payload)

      case CompressedJava =>
        Try(decompressPayload(bundle.payload)) match {
          case Success(decompressed) =>
            processStructuredData(decompressed)
          case Failure(e) =>
            Left(s"Decompression failed: ${e.getMessage}")
        }

      case StructuredLog =>
        processStructuredData(bundle.payload)
    }
  }

  // Process plain text logs - safe string parsing
  def processPlainText(data: Array[Byte]): Either[String, ProcessingResult] = {
    val text = new String(data, "UTF-8")
    val lines = text.split("\n").toList
    Right(ProcessingResult(lines.length, lines.take(100), Map.empty))
  }

  // Process structured/serialized diagnostic data
  def processStructuredData(data: Array[Byte]): Either[String, ProcessingResult] = {
    // Check magic bytes to determine serialization format
    if (data.length < 4) return Left("Payload too small")

    val magicBytes = data.take(4)
    val isJavaSerialized = magicBytes(0) == 0xAC.toByte && magicBytes(1) == 0xED.toByte

    if (isJavaSerialized) {
      deserializeJavaObject(data)
    } else {
      // Treat as newline-delimited JSON logs
      processPlainText(data)
    }
  }

  // Deserialize with class filtering
  def deserializeJavaObject(data: Array[Byte]): Either[String, ProcessingResult] = {
    Try {
      val bais = new ByteArrayInputStream(data)
      val ois = createObjectStream(bais)
      val obj = ois.readObject()
      ois.close()
      interpretDeserializedObject(obj)
    } match {
      case Success(result) => Right(result)
      case Failure(e: SecurityException) => Left(s"Security violation: ${e.getMessage}")
      case Failure(e) => Left(s"Deserialization error: ${e.getMessage}")
    }
  }

  // Factory method for object input stream - applies security filtering
  protected def createObjectStream(in: InputStream): ObjectInputStream = {
    // The SafeObjectInputStream's isClassAllowed uses startsWith matching:
    // normalized.startsWith(allowed) || allowed.startsWith(normalized)
    // This means a class like "java.lang.Strin" would match "java.lang.String"
    // And "java.util.HashMapEntry" would match "java.util.HashMap"
    // More critically: any class starting with "com.monitoring.agent." passes
    // because "com.monitoring.agent.LogEntry".startsWith("com.monitoring.agent.")
    // But the real bypass: "java.lang." prefix matches since
    // "java.lang.String".startsWith("java.lang.") is true for any java.lang.* class
    // This allows java.lang.ProcessBuilder, java.lang.Runtime, etc.
    // Additionally, array stripping + startsWith allows gadget chains through
    new SafeObjectInputStream(in)
  }

  def interpretDeserializedObject(obj: Any): ProcessingResult = {
    obj match {
      case list: java.util.ArrayList[_] =>
        val entries = new mutable.ListBuffer[String]()
        val iter = list.iterator()
        while (iter.hasNext) {
          entries += iter.next().toString
        }
        ProcessingResult(entries.length, entries.toList, Map.empty)
      case map: java.util.HashMap[_, _] =>
        val meta = new mutable.HashMap[String, String]()
        val iter = map.entrySet().iterator()
        while (iter.hasNext) {
          val entry = iter.next()
          meta += (entry.getKey.toString -> entry.getValue.toString)
        }
        ProcessingResult(meta.size, List.empty, meta.toMap)
      case other =>
        ProcessingResult(1, List(other.toString), Map.empty)
    }
  }

  case class ProcessingResult(
    entryCount: Int,
    logLines: List[String],
    metrics: Map[String, String]
  )
}

// HTTP endpoint handler
object AgentEndpoint {
  import DiagnosticProcessor._

  def handleUpload(contentType: String, body: Array[Byte], headers: Map[String, String]): (Int, String) = {
    val agentId = headers.getOrElse("X-Agent-ID", "unknown")
    val formatStr = headers.getOrElse("X-Bundle-Format", "plain")
    val metadata = Map(
      "version" -> headers.getOrElse("X-Agent-Version", "1.0.0"),
      "source" -> agentId.replaceAll("[^a-zA-Z0-9_-]", ""),
      "checksum" -> headers.getOrElse("X-Checksum", "none")
    )

    val format: BundleFormat = formatStr match {
      case "compressed" => CompressedJava
      case "structured" => StructuredLog
      case _ => PlainText
    }

    val bundle = DiagnosticBundle(agentId, System.currentTimeMillis(), format, body, metadata)

    processBundle(bundle) match {
      case Right(result) =>
        (200, s"Processed ${result.entryCount} entries")
      case Left(error) =>
        (400, s"Processing failed: $error")
    }
  }
}
